[ExtensionOf(classStr(VendInvoiceEventHandler))]
final class METVendInvoiceEventHandler_Extension
{
    private VendInvoiceInfoTable claimInvoiceTable;

}

Method.Source:
    public void started(WorkflowEventArgs _workflowEventArgs)
    {
        VendInvoiceInfoTable    savedVendInvoiceInfoTable = VendInvoiceInfoTable::findRecId(_workflowEventArgs.parmWorkflowContext().parmRecId());
        METVendInvoiceMatching  invoiceMatching = METVendInvoiceMatching::construct();


        if (savedVendInvoiceInfoTable.RecId != 0)
        {
            invoiceMatching.parmVendInvoiceInfoTable(savedVendInvoiceInfoTable);
            invoiceMatching.generateFailureMatchingLines();
        }

        next started(_workflowEventArgs);
    }

    public void completed(WorkflowEventArgs _workflowEventArgs)
    {
        vendInvoiceInfoLine vendInvoiceLine;

        next completed(_workflowEventArgs);

        ttsbegin;

        VendInvoiceInfoTable vendorInvoice = VendInvoiceInfoTable::findRecId(_workflowEventArgs.parmWorkflowContext().parmRecId());

        while select forupdate vendInvoiceLine
                    where vendInvoiceLine.ParmId        == vendorInvoice.ParmId &&
                          vendInvoiceLine.TableRefId    == vendorInvoice.TableRefId
        {
            if(vendInvoiceLine.isNonPO() && vendInvoiceLine.MetClaimLine)
            {
                this.createClaimLine(vendInvoiceLine);
            }
        }

        ttscommit;

        this.submitClaimInvoiceToWorkflow();
    }

private void submitClaimInvoiceToWorkflow()
{
    if(claimInvoiceTable && claimInvoiceTable.existLine() && claimInvoiceTable.canSubmitToWorkflow())
    {
        VendInvoiceHeaderWorkflow::submitToWorkflow(claimInvoiceTable, claimInvoiceTable.Description);
    }
}

    protected void createClaimLine(VendInvoiceInfoLine _invoiceLine)
    {
        VendInvoiceInfoLine claimLine;

        if(!this.claimInvoiceTable)
        {
            this.createClaimInvoiceHeader(_invoiceLine.vendInvoiceInfoTable());
        }

        claimLine.clear();
        claimLine.initValue();

        claimLine.ParmId                 = claimInvoiceTable.ParmId;
        claimLine.TableRefId             = claimInvoiceTable.TableRefId;
        claimLine.currencyCode           = _invoiceLine.currencyCode;
        claimLine.AddressRefRecId        = _invoiceLine.AddressRefRecId;
        claimLine.AddressRefTableId      = _invoiceLine.AddressRefTableId;
        claimLine.DeliveryName           = _invoiceLine.DeliveryName;
        claimLine.DeliveryPostalAddress  = _invoiceLine.DeliveryPostalAddress;
        claimLine.MetTransRefId          = _invoiceLine.RecId;
        
        claimLine.ItemId                 = _invoiceLine.ItemId;
        claimLine.modifiedField(fieldNum(VendInvoiceInfoLine, ItemId));

        claimLine.MetExtComment          = _invoiceLine.MetExtComment;
            
        claimLine.TaxGroup               = _invoiceLine.TaxGroup;
        claimLine.TaxItemGroup           = _invoiceLine.TaxItemGroup;
        claimLine.DefaultDimension       = _invoiceLine.DefaultDimension;
        claimLine.InventDimId            = _invoiceLine.InventDimId;

        claimLine.ReasonTableRef         = _invoiceLine.ReasonTableRef;
        claimLine.Description            = _invoiceLine.Description;

        claimLine.PurchPrice             = _invoiceLine.PurchPrice;
        claimLine.modifiedField(fieldNum(VendInvoiceInfoLine, PurchPrice));

        claimLine.ReceiveNow            = _invoiceLine.ReceiveNow * -1;
        claimLine.PdsCWReceiveNow       = _invoiceLine.PdsCWReceiveNow * -1;

        claimLine.vendDocumentLineInterface().modifiedReceiveNowWithPromptDefault(abs(claimLine.PdsCWReceiveNow) > 0, UnknownNoYes::Yes);

        if(claimLine.validateWrite())
        {
            claimLine.insert();
        }
    }

    private void createClaimInvoiceHeader(VendInvoiceInfoTable _originalInvoice)
    {
        claimInvoiceTable.clear();
        claimInvoiceTable.initValue();
        claimInvoiceTable.initFromActiveHeader(_originalInvoice);
        claimInvoiceTable.TableRefId = formletterParmData::getNewTableRefId();
        claimInvoiceTable.ImportedAmount = 0;
        claimInvoiceTable.ImportedSalesTax = 0;

        claimInvoiceTable.Num = strFmt("%1 - %2", _originalInvoice.Num, METConstants::VendInvoiceInfoCreditNoteSuffix);
        claimInvoiceTable.Description = strFmt("@MET:ClaimInvoiceDescription",_originalInvoice.Num, _originalInvoice.PurchId);

        if(claimInvoiceTable.validateWrite())
        {
            claimInvoiceTable.insert();
            claimInvoiceTable.reread();
        }
    }
